-- events.organizer_id used to hold a USER id. It now holds an ORGANIZER PROFILE id
-- (organizer_profiles.id), so only an organizer can own an event.
--
-- Generated by drizzle-kit, then edited by hand: steps 2 and 3 are the data migration that
-- drizzle-kit cannot write. The migrator runs this whole file in one transaction, so if any
-- step fails nothing is changed.

-- 1. Drop the old link to users (the next step puts profile ids in the column).
ALTER TABLE "events" DROP CONSTRAINT "events_organizer_id_users_id_fk";
--> statement-breakpoint

-- 2. Convert every existing event: owner's user id -> that user's organizer profile id.
-- A profile id and a user id are different random uuids, so this can never touch a row twice.
UPDATE "events"
SET "organizer_id" = "organizer_profiles"."id"
FROM "organizer_profiles"
WHERE "organizer_profiles"."user_id" = "events"."organizer_id";
--> statement-breakpoint

-- 3. Stop with a readable message if an event is owned by someone with no organizer profile
-- (for example an event an admin created). Fix those rows first, then run the migration again.
DO $$
DECLARE
  orphan record;
BEGIN
  SELECT e."id", e."title" INTO orphan
  FROM "events" e
  WHERE NOT EXISTS (
    SELECT 1 FROM "organizer_profiles" p WHERE p."id" = e."organizer_id"
  )
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'Event % (%) is not owned by an organizer profile. Reassign or delete it, then migrate again.',
      orphan."id", orphan."title";
  END IF;
END $$;
--> statement-breakpoint

-- 4. The new link: an event belongs to an organizer profile.
ALTER TABLE "events" ADD CONSTRAINT "events_organizer_id_organizer_profiles_id_fk" FOREIGN KEY ("organizer_id") REFERENCES "public"."organizer_profiles"("id") ON DELETE restrict ON UPDATE no action;
